{"implementation": "def solve(case):
    initial = case['initial_state']
    max_steps = case['max_steps']
    tool_obs = case['tool_observations']
    transitions = case['transitions']
    trace = []
    current = initial
    step = 0
    while True:
        if current not in transitions:
            break
        state_def = transitions[current]
        if state_def['kind'] == 'final':
            return {'final': state_def['value'], 'status': 'success', 'trace': trace}
        if step >= max_steps:
            break
        action = state_def['action']
        if action in tool_obs:
            observation = tool_obs[action]
        else:
            observation = 'invalid'
        next_state = state_def.get('next_by_observation', {}).get(observation, state_def.get('default_next'))
        step += 1
        trace.append({'step': step, 'action': action, 'observation': observation, 'state': next_state})
        current = next_state
    return {'final': None, 'status': 'max_steps_exceeded', 'trace': trace}"}
